#
#  æ­¤æ–‡ä»¶æ˜¯è‡ªåŒ…å«çš„ï¼Œåªéœ€ä¸€ä¸ªæ–‡ä»¶å³å¯å®Œæˆéƒ¨ç½²ã€‚
# ============================================================
set -euo pipefail

# â”€â”€â”€ é…ç½® â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
DEPLOY_DIR="${GRIDSIM_DEPLOY_DIR:-/home/envuser/IEC/gridsim}"
BACKUP_DIR="${DEPLOY_DIR}/backups"
SERVICE_NAME="gridsim"
API_PORT="${GRIDSIM_PORT:-8989}"
API_URL="http://localhost:${API_PORT}/api/v1/status"
ARCHIVE_MARKER="__ARCHIVE_BELOW__"
VERSION="3.2.0-dev-3.9331e35"

# â”€â”€â”€ é¢œè‰² â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'; CYAN='\033[0;36m'; NC='\033[0m'
info()  { echo -e "${GREEN}[INFO]${NC} $*"; }
warn()  { echo -e "${YELLOW}[WARN]${NC} $*"; }
err()   { echo -e "${RED}[ERR]${NC} $*" >&2; exit 1; }
step()  { echo -e "${CYAN}[$1/$TOTAL_STEPS]${NC} $2"; }

fmt_size() {
    local bytes=$1
    if [ "$bytes" -lt 1024 ]; then echo "${bytes}B"
    elif [ "$bytes" -lt 1048576 ]; then echo "$(( bytes / 1024 ))KB"
    elif [ "$bytes" -lt 1073741824 ]; then echo "$(( bytes / 1048576 ))MB"
    else echo "$(( bytes / 1073741824 ))GB"; fi
}

# â”€â”€â”€ ä»Žè‡ªèº«æå–åŽ‹ç¼©åŒ… â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
extract_archive() {
    local target="$1"
    local archive_line
    archive_line=$(grep -n "^${ARCHIVE_MARKER}$" "$0" | tail -1 | cut -d: -f1)
    [ -z "$archive_line" ] && err "æ— æ³•æ‰¾åˆ°å†…åµŒçš„åŽ‹ç¼©åŒ…æ•°æ®"
    tail -n +$((archive_line + 1)) "$0" | tar xzf - -C "$target" --strip-components=1
}

# â”€â”€â”€ æœåŠ¡æŽ§åˆ¶ â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
do_stop() {
    info "åœæ­¢ ${SERVICE_NAME} æœåŠ¡..."
    systemctl stop "$SERVICE_NAME" 2>/dev/null || true
    if [ -x "${DEPLOY_DIR}/bin/stop.sh" ]; then
        bash "${DEPLOY_DIR}/bin/stop.sh" 2>/dev/null || true
    fi
    pkill -x "$SERVICE_NAME" 2>/dev/null || true
    pkill -f "${SERVICE_NAME} serve" 2>/dev/null || true
    sleep 1
    if pgrep -x "$SERVICE_NAME" >/dev/null 2>&1; then
        pkill -9 -x "$SERVICE_NAME" 2>/dev/null || true
        sleep 1
    fi
    info "æœåŠ¡å·²åœæ­¢"
}

do_start() {
    info "å¯åŠ¨ ${SERVICE_NAME} æœåŠ¡..."
    if systemctl start "$SERVICE_NAME" 2>/dev/null; then
        info "  systemctl start æˆåŠŸ"
        return 0
    fi
    if [ -x "${DEPLOY_DIR}/bin/start.sh" ]; then
        if bash "${DEPLOY_DIR}/bin/start.sh" 2>/dev/null; then
            info "  start.sh å¯åŠ¨æˆåŠŸ"
            return 0
        fi
    fi
    # å›žé€€ï¼šç›´æŽ¥å¯åŠ¨
    mkdir -p "${DEPLOY_DIR}/logs"
    cd "$DEPLOY_DIR"
    nohup "${DEPLOY_DIR}/bin/${SERVICE_NAME}" serve \
        --http ":${API_PORT}" \
        --config-dir "${DEPLOY_DIR}/config" \
        --log-dir "${DEPLOY_DIR}/logs" \
        --log info \
        > "${DEPLOY_DIR}/logs/output.log" 2>&1 &
    echo $! > "${DEPLOY_DIR}/logs/pid"
    info "  ç›´æŽ¥å¯åŠ¨æˆåŠŸ (PID: $!)"
}

do_restart() {
    do_stop
    sleep 1
    do_start
}

# â”€â”€â”€ systemd æœåŠ¡æ³¨å†Œ â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
ensure_systemd() {
    local unit_path="/etc/systemd/system/${SERVICE_NAME}.service"
    if [ -f "$unit_path" ]; then
        # æ›´æ–° WorkingDirectoryï¼ˆå¦‚æžœéƒ¨ç½²ç›®å½•å˜äº†ï¼‰
        if ! grep -q "$DEPLOY_DIR" "$unit_path" 2>/dev/null; then
            sed -i "s|WorkingDirectory=.*|WorkingDirectory=${DEPLOY_DIR}|" "$unit_path"
            sed -i "s|ExecStart=.*|ExecStart=/bin/bash ${DEPLOY_DIR}/bin/start.sh|" "$unit_path"
            sed -i "s|ExecStop=.*|ExecStop=/bin/bash ${DEPLOY_DIR}/bin/stop.sh|" "$unit_path"
            sed -i "s|PIDFile=.*|PIDFile=${DEPLOY_DIR}/logs/pid|" "$unit_path"
            systemctl daemon-reload 2>/dev/null || true
            info "  systemd å•å…ƒè·¯å¾„å·²æ›´æ–°"
        fi
        return 0
    fi

    info "  åˆ›å»º systemd æœåŠ¡å•å…ƒ..."
    cat > "$unit_path" << UNIT
[Unit]
Description=Grid Simulator
After=network.target

[Service]
Type=forking
User=root
WorkingDirectory=${DEPLOY_DIR}
ExecStart=/bin/bash ${DEPLOY_DIR}/bin/start.sh
ExecStop=/bin/bash ${DEPLOY_DIR}/bin/stop.sh
PIDFile=${DEPLOY_DIR}/logs/pid
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload 2>/dev/null || true
    systemctl enable "$SERVICE_NAME" 2>/dev/null || true
    info "  systemd æœåŠ¡å·²æ³¨å†Œ"
}

# â”€â”€â”€ å¥åº·æ£€æŸ¥ â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
health_check() {
    info "å¥åº·æ£€æŸ¥..."
    local ok=false
    for i in $(seq 1 5); do
        local http_code
        http_code=$(curl -s -o /dev/null -w "%{http_code}" "$API_URL" 2>/dev/null || echo "000")
        if [ "$http_code" = "200" ]; then
            ok=true
            break
        fi
        [ "$i" -lt 5 ] && sleep 3
    done

    if [ "$ok" = true ]; then
        info "  âœ… API: HTTP 200 OK"
        local status_json
        status_json=$(curl -s "$API_URL" 2>/dev/null || echo "{}")
        local running_ver=$(echo "$status_json" | grep -o '"version":"[^"]*"' | cut -d'"' -f4)
        [ -n "$running_ver" ] && info "  âœ… è¿è¡Œç‰ˆæœ¬: $running_ver"
        local instances
        instances=$(curl -s "http://localhost:${API_PORT}/api/v1/instances" 2>/dev/null || echo "[]")
        local inst_count=$(echo "$instances" | grep -o '"id"' | wc -l)
        info "  âœ… å®žä¾‹æ•°: $inst_count"
        return 0
    else
        warn "  âš  API æœªè¿”å›ž 200ï¼ˆæœåŠ¡å¯èƒ½éœ€è¦æ›´å¤šå¯åŠ¨æ—¶é—´ï¼‰"
        return 1
    fi
}

# â”€â”€â”€ æŸ¥çœ‹çŠ¶æ€ â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
show_status() {
    echo "â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•"
    echo "  GridSim æœåŠ¡çŠ¶æ€"
    echo "â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•"
    echo ""
    if systemctl is-active --quiet "$SERVICE_NAME" 2>/dev/null; then
        info "systemd: active"
    else
