}

# â”€â”€â”€ å…¥å£ â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
case "${1:-}" in
    --extract-only)
        TARGET="${2:-.}"
        info "ä»…è§£åŽ‹åˆ°: $TARGET"
        mkdir -p "$TARGET"
        extract_archive "$TARGET"
        info "è§£åŽ‹å®Œæˆ"
        ;;
    --target)
